"""Legacy EXPORT_ACCT fixed-width record formatter."""

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _text(value: Any) -> str:
    return "" if value is None else str(value)


def _fixed(value: Any, width: int) -> str:
    return _text(value)[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if value is None or value == "":
        value = 0

    cents = (Decimal(str(value)) * Decimal(100)).to_integral_value(
        rounding=ROUND_HALF_UP
    )
    return str(cents).zfill(width)


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT record without a terminator."""
    cred_hold = row.get("CRED_HOLD", "")
    if cred_hold is None or cred_hold == "":
        cred_hold = "N"

    create_dt = row.get("CREATE_DT", "")
    if create_dt is None or create_dt == "":
        create_dt = "00000000"

    return (
        _fixed(row.get("ACCT_ID", ""), 10)
        + _fixed(row.get("ACCT_NM", ""), 40)
        + _fixed(row.get("REGION_CD", ""), 3)
        + _zpad_cents(row.get("ANN_REV", ""), 15)
        + str(cred_hold)
        + str(create_dt)
    )
